const HospitalDetailsWrapper: React.FC = () => (
  <HospitalDetails
    icuBeds={{ total: 50, available: 15, occupied: 35, covid: 10, nonCovid: 25, emergency: 5, cardiac: 8, pediatric: 5, neonatal: 2 }}
    resources={[]}
    staff={[]}
  />
);

// ============================================
// MAIN ROUTES
// ============================================
export const AppRoutes: React.FC = () => {
  return (
    <Suspense fallback={<PageLoader />}>
      <Routes>
        {routeConfig.map((route) => {
          const Component = route.component;

          // Special case for hospital/:id with props
          if (route.path === '/hospital/:id') {
            return (
              <Route
                key={route.path}
                path={route.path}
                element={<HospitalDetailsWrapper />}
              />
            );
          }

          // Protected routes
          if (route.isProtected) {
            return (
              <Route
                key={route.path}
                path={route.path}
                element={
                  <AuthGuard route={route}>
                    <Component />
                  </AuthGuard>
                }
              />
            );
          }

          // Login/Register - redirect if already logged in
          if (route.path === '/login' || route.path === '/register') {
            return (
              <Route
                key={route.path}
                path={route.path}
                element={
                  <PublicGuard>
                    <Component />
                  </PublicGuard>
                }
              />
            );
          }

          // Public routes
          return (
            <Route
              key={route.path}
              path={route.path}
              element={<Component />}
            />
          );
        })}
      </Routes>
    </Suspense>
  );
};

